/*
 * cold/test/test_cold_map_table.c - the COLD map-table record against the
 * image bytes
 *
 * Generated by: Claude Opus 5.5
 *
 * cold/sau2/cold_start.s is byte-checked against the image by
 * tools/asm_compare.py; this host test checks that cold/cold.h's
 * cold_map_entry_t describes the same 10-byte records, by decoding three
 * entries of the image's table at 0x101850 (bytes copied from the image
 * file, offsets 0x450..) with the record's offsets and big-endian fields.
 */

#include <stdio.h>
#include <stddef.h>
#include "cold/cold.h"

static int failures = 0;
#define ASSERT_EQ(exp, act) do { \
    unsigned long _e = (unsigned long)(exp), _a = (unsigned long)(act); \
    if (_e != _a) { printf("  FAIL %s:%d: %s = 0x%lx, expected 0x%lx\n", \
                           __FILE__, __LINE__, #act, _a, _e); failures++; } \
} while (0)
#define RUN_TEST(t) do { printf("%s\n", #t); t(); } while (0)

static unsigned be16(const unsigned char *p) { return (p[0] << 8) | p[1]; }
static unsigned long be32(const unsigned char *p)
{
    return ((unsigned long)p[0] << 24) | ((unsigned long)p[1] << 16) |
           ((unsigned long)p[2] << 8) | p[3];
}

/* 0x101864 PFT, 0x1018C8 DUMP, 0x1018DC COLD itself */
static const unsigned char pft[10]  = { 0x00,0x10, 0x00,0x10, 0x00,0xff,0xb8,0x00, 0x01,0x60 };
static const unsigned char dump[10] = { 0x00,0x01, 0x04,0x03, 0x80,0xe0,0x04,0x00, 0x01,0x70 };
static const unsigned char cold[10] = { 0x00,0x02, 0x04,0x05, 0x60,0x10,0x14,0x00, 0x01,0x70 };

static void test_layout(void)
{
    ASSERT_EQ(10, sizeof(cold_map_entry_t));
    ASSERT_EQ(0, offsetof(cold_map_entry_t, count));
    ASSERT_EQ(2, offsetof(cold_map_entry_t, ppn));
    ASSERT_EQ(4, offsetof(cold_map_entry_t, va));
    ASSERT_EQ(8, offsetof(cold_map_entry_t, prot));
}

static void test_decode(void)
{
    size_t c = offsetof(cold_map_entry_t, count);
    size_t p = offsetof(cold_map_entry_t, ppn);
    size_t v = offsetof(cold_map_entry_t, va);
    size_t r = offsetof(cold_map_entry_t, prot);

    ASSERT_EQ(0x10, be16(pft + c));
    ASSERT_EQ(0x10, be16(pft + p));
    ASSERT_EQ(0x00FFB800, be32(pft + v));
    ASSERT_EQ(0x160, be16(pft + r));

    ASSERT_EQ(0x403, be16(dump + p));
    ASSERT_EQ(COLD_MAP_WIRED | 0x00E00400, be32(dump + v));
    ASSERT_EQ(0x170, be16(dump + r));

    ASSERT_EQ(2, be16(cold + c));
    ASSERT_EQ(0x405, be16(cold + p));
    ASSERT_EQ(COLD_MAP_COLD | COLD_MAP_PRIVATE | COLD_RFC_LOAD_ADDR, be32(cold + v));
}

int main(void)
{
    RUN_TEST(test_layout);
    RUN_TEST(test_decode);
    printf("%s\n", failures ? "FAILED" : "PASSED");
    return failures ? 1 : 0;
}
